/**
 * HTML sitemap (insan-okur /sitemap dizin sayfaları) veri servisi.
 *
 * XML sitemap'ten (registry.ts) farklı olarak başlık + hiyerarşi taşıyan
 * apiv3 `sitemap/directory/*` uçlarını tüketir. Filtre sözleşmesi XML
 * feed'iyle birebir aynıdır (yalnız yayında + kendi canonical'ı olan
 * sayfalar), bu yüzden HTML sitemap ile sitemap.xml asla çelişmez.
 */
import { apiv3Get } from "@/lib/apiv3";

export const SITEMAP_DIRECTORY_REVALIDATE = 86400;

/** Tur dizininde sayfa başına link sayısı (~32 sayfa). */
export const SITEMAP_TOURS_PER_PAGE = 250;

export type SitemapCategoryItem = {
  id: number;
  parentId: number | null;
  pageUrl: string;
  /** Yer nitelikli tam başlık ("Europe Eco Tours") — düz listeler için. */
  title: string;
  /** Ebeveyn bağlamında kısa ad ("Eco Tours", "Abu Simbel Tours") — ağaç görünümü için. */
  shortTitle: string;
  pageCategoryType: "continent" | "country" | "city" | null;
  paramCategory: string | null;
  sourceType: string | null;
  tourCount: number;
};

export type SitemapTourItem = {
  slug: string;
  name: string;
  durationDays: number | null;
};

export type SitemapToursPage = {
  total: number;
  perPage: number;
  page: number;
  items: SitemapTourItem[];
};

export async function getSitemapDirectoryCategories(): Promise<
  SitemapCategoryItem[]
> {
  const res = await apiv3Get("/sitemap/directory/tour-categories", {
    revalidate: SITEMAP_DIRECTORY_REVALIDATE,
  });
  if (!res.ok) {
    throw new Error(`sitemap directory categories failed: ${res.status}`);
  }
  const data = (await res.json()) as { items: SitemapCategoryItem[] };
  return data.items;
}

export async function getSitemapDirectoryTours(
  page: number,
): Promise<SitemapToursPage> {
  const res = await apiv3Get(
    `/sitemap/directory/tours?page=${page}&per=${SITEMAP_TOURS_PER_PAGE}`,
    { revalidate: SITEMAP_DIRECTORY_REVALIDATE },
  );
  if (!res.ok) {
    throw new Error(`sitemap directory tours failed: ${res.status}`);
  }
  return (await res.json()) as SitemapToursPage;
}

export type DestinationNode = SitemapCategoryItem & {
  children: DestinationNode[];
};

/**
 * Destinasyon sayfalarını (paramCategory olmayanlar) parentId üzerinden
 * ağaca çevirir; her seviye alfabetik. Kök tipik olarak tek "worldwide"
 * sayfasıdır — sayfa tarafı tek kökü lead-link olarak ele alır.
 */
export function buildDestinationTree(
  items: SitemapCategoryItem[],
): DestinationNode[] {
  const nodes = new Map<number, DestinationNode>();
  for (const item of items) {
    if (!item.paramCategory) nodes.set(item.id, { ...item, children: [] });
  }

  const roots: DestinationNode[] = [];
  for (const node of Array.from(nodes.values())) {
    const parent = node.parentId ? nodes.get(node.parentId) : undefined;
    if (parent) parent.children.push(node);
    else roots.push(node);
  }

  const sortDeep = (list: DestinationNode[]) => {
    list.sort((a, b) => a.title.localeCompare(b.title));
    for (const node of list) sortDeep(node.children);
  };
  sortDeep(roots);

  return roots;
}

export type SitemapCategoryGroup = {
  key: string;
  title: string;
  /** Grubun globali (kıtasız/ülkesiz ana kategori sayfası); heading buna link olur. */
  headerItem: SitemapCategoryItem | null;
  items: SitemapCategoryItem[];
};

/** Kategori sayfalarını (paramCategory olanlar) tema bazında gruplar; gruplar ve içerikleri alfabetik. */
export function groupCategoryPages(
  items: SitemapCategoryItem[],
): SitemapCategoryGroup[] {
  const groups = new Map<string, SitemapCategoryGroup>();

  for (const item of items) {
    if (!item.paramCategory) continue;

    let group = groups.get(item.paramCategory);
    if (!group) {
      group = {
        key: item.paramCategory,
        title: titleizeSlug(item.paramCategory),
        headerItem: null,
        items: [],
      };
      groups.set(item.paramCategory, group);
    }

    if (item.sourceType === "category" || item.sourceType === "worldwide") {
      group.headerItem = item;
      group.title = item.title;
    } else {
      group.items.push(item);
    }
  }

  const result = Array.from(groups.values());
  for (const group of result) {
    group.items.sort((a, b) => a.title.localeCompare(b.title));
  }

  return result.sort((a, b) => a.title.localeCompare(b.title));
}

function titleizeSlug(slug: string): string {
  return slug
    .split("-")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}
