/**
 * HTML sitemap dizin sayfalarının ortak iskeleti: standart Breadcrumb
 * (JSON-LD dahil) + h1 + intro. Yerleşim blog listesiyle aynı desendedir.
 */
import Breadcrumb from "@/components/header/breadcrumb";

export const sitemapLinkClass =
  "tw-text-[14px] sm:tw-text-[15px] tw-leading-relaxed tw-text-[#5d556c] hover:tw-text-[#854ec9] tw-transition-colors tw-duration-200 tw-no-underline";

export const sitemapSectionHeadingClass =
  "tw-m-0 tw-text-[20px] md:tw-text-[24px] tw-font-bold tw-tracking-tight tw-text-[#14101c]";

export const sitemapColumnsClass =
  "tw-list-none tw-m-0 tw-p-0 tw-columns-2 md:tw-columns-3 lg:tw-columns-4 tw-gap-x-8 [&>li]:tw-mb-1.5 [&>li]:tw-break-inside-avoid";

type Crumb = { pageTitle: string; pageUrl: string };

export default function SitemapShell({
  title,
  intro,
  crumbs,
  children,
}: {
  title: string;
  intro?: string;
  /** "Home" otomatik; buraya Sitemap ve varsa alt sayfa gelir. */
  crumbs: Crumb[];
  children: React.ReactNode;
}) {
  return (
    <main className="tw-font-display tw-bg-white">
      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-my-6">
        <Breadcrumb items={crumbs} />

        <div className="tw-mb-8">
          <h1 className="tw-text-[clamp(28px,4vw,40px)] tw-font-extrabold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            {title}
          </h1>
          {intro && (
            <p className="tw-mt-2 tw-mb-0 tw-max-w-[70ch] tw-text-[15px] tw-leading-[1.6] tw-text-[#5d556c]">
              {intro}
            </p>
          )}
        </div>

        {children}
      </div>
    </main>
  );
}
